import React, { useState, useEffect, useRef } from "react";
import axios from "axios";
import MessageBubble from "./MessageBubble.css";
import "./DebateArena.css";

function DebateArena({ topic, onReset }) {
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [round, setRound] = useState(0);
  const bottomRef = useRef(null);
  const inputRef = useRef(null);

  useEffect(() => {
    startDebate();
    // eslint-disable-next-line
  }, []);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages, isLoading]);

  const startDebate = async () => {
    setIsLoading(true);
    const openingMessage = {
      role: "user",
      content: `The debate topic is: "${topic}". I will be arguing FOR this statement. You argue AGAINST it. Open the debate with your counter-argument.`,
    };

    try {
      const res = await axios.post("http://localhost:5000/api/debate", {
        topic,
        messages: [openingMessage],
      });
      setMessages([{ role: "assistant", content: res.data.reply, isOpening: true }]);
      setRound(1);
    } catch (err) {
      setMessages([{ role: "assistant", content: "Hmm, I lost my voice! Check if the backend is running! 🎤", isError: true }]);
    } finally {
      setIsLoading(false);
      inputRef.current?.focus();
    }
  };

  const sendMessage = async () => {
    const userText = input.trim();
    if (!userText || isLoading) return;

    const newUserMsg = { role: "user", content: userText };
    const history = [
      { role: "user", content: `The debate topic is: "${topic}". I will argue FOR this. You argue AGAINST it.` },
      ...messages.map((m) => ({ role: m.role, content: m.content })),
      newUserMsg,
    ];

    setMessages((prev) => [...prev, newUserMsg]);
    setInput("");
    setIsLoading(true);

    try {
      const res = await axios.post("http://localhost:5000/api/debate", { topic, messages: history });
      setMessages((prev) => [...prev, { role: "assistant", content: res.data.reply }]);
      setRound((r) => r + 1);
    } catch (err) {
      setMessages((prev) => [...prev, { role: "assistant", content: "I crashed! That argument was too powerful... or the server is down 😅", isError: true }]);
    } finally {
      setIsLoading(false);
      inputRef.current?.focus();
    }
  };

  const handleKeyDown = (e) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      sendMessage();
    }
  };

  return (
    <div className="arena-wrapper">
      <div className="topic-bar">
        <div className="topic-info">
          <span className="topic-label">Debating:</span>
          <span className="topic-text">"{topic}"</span>
        </div>
        <div className="arena-meta">
          <span className="round-badge">Round {round}</span>
          <button className="reset-btn" onClick={onReset}>New Topic</button>
        </div>
      </div>

      <div className="players">
        <div className="player you">
          <span className="player-icon">🧑</span>
          <div>
            <div className="player-name">You</div>
            <div className="player-side">FOR the topic</div>
          </div>
        </div>
        <div className="vs">VS</div>
        <div className="player ai">
          <span className="player-icon">🤖</span>
          <div>
            <div className="player-name">Claude AI</div>
            <div className="player-side">AGAINST the topic</div>
          </div>
        </div>
      </div>

      <div className="chat-window">
        {messages.length === 0 && isLoading && (
          <div className="opening-loader">
            <div className="typing-indicator"><span /><span /><span /></div>
            <p>Claude is warming up its counter-arguments...</p>
          </div>
        )}
        {messages.map((msg, idx) => (
          <MessageBubble key={idx} message={msg} />
        ))}
        {isLoading && messages.length > 0 && (
          <div className="ai-typing">
            <div className="ai-avatar-box">🤖</div>
            <div className="typing-bubble">
              <div className="typing-indicator"><span /><span /><span /></div>
            </div>
          </div>
        )}
        <div ref={bottomRef} />
      </div>

      <div className="input-area">
        <textarea
          ref={inputRef}
          className="debate-input"
          placeholder="Type your argument here... (Enter to send)"
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onKeyDown={handleKeyDown}
          rows={2}
          disabled={isLoading}
        />
        <button
          className="send-btn"
          onClick={sendMessage}
          disabled={isLoading || !input.trim()}
        >
          {isLoading ? "..." : "Send ⚡"}
        </button>
      </div>
      <p className="input-hint">Press Enter to send · Shift+Enter for new line</p>
    </div>
  );
}

export default DebateArena;
